'use strict';

const PHASES = new Set(['queued', 'active', 'resolved']);

function validRecord(record) {
  return record && Number.isInteger(record.key) && record.key > 0 &&
    typeof record.summary === 'string' && record.summary.length > 0 &&
    typeof record.details === 'string' && record.details.length > 0 &&
    PHASES.has(record.phase);
}

function copyRecord(record) {
  return {
    key: record.key,
    summary: record.summary,
    details: record.details,
    phase: record.phase
  };
}

function copyState(state) {
  return state.map(copyRecord);
}

function handleDefect(state, command) {
  if (!Array.isArray(state) || !state.every(validRecord)) {
    return { status: 400, body: { error: 'Invalid input' }, state: [] };
  }

  const next = copyState(state);
  if (!command || typeof command !== 'object' || Array.isArray(command)) {
    return { status: 400, body: { error: 'Invalid input' }, state: copyState(next) };
  }

  if (command.type === 'list') {
    const ordered = next.slice().sort((a, b) => a.key - b.key);
    return { status: 200, body: copyState(ordered), state: copyState(next) };
  }

  if (command.type === 'get' && Number.isInteger(command.key) && command.key > 0) {
    const found = next.find((record) => record.key === command.key);
    return found
      ? { status: 200, body: copyRecord(found), state: copyState(next) }
      : { status: 404, body: { error: 'Defect not found' }, state: copyState(next) };
  }

  if (command.type === 'add' && validRecord(command.record)) {
    if (next.some((record) => record.key === command.record.key)) {
      return { status: 409, body: { error: 'Duplicate key' }, state: copyState(next) };
    }
    const added = copyRecord(command.record);
    next.push(added);
    return { status: 201, body: copyRecord(added), state: copyState(next) };
  }

  return { status: 400, body: { error: 'Invalid input' }, state: copyState(next) };
}

module.exports = { handleDefect };
